code.installcode:
$base = '/home/hddrecov/public_html/forum';
$branch = 'cursor/vbdl-post-upload-acl-grants-376d';
$raw = 'https://raw.githubusercontent.com/petersany325/petersany325/' . $branch . '/forum-vbdlmanager/live';
$map = array(
  '/vbdlmanager/assets/post-upload.js' => '/vbdlmanager/assets/post-upload.js',
  '/vbdlmanager/assets/quickupload-widget.html' => '/vbdlmanager/assets/quickupload-widget.html',
  '/core/packages/vbdlportal/hooks.php' => '/core/packages/vbdlportal/hooks.php',
);
$out = array('rev'=>'mc9','branch'=>$branch,'ts'=>time());
foreach ($map as $rel => $path) {
  $url = $raw . $path;
  $bin = false;
  if (function_exists('curl_init')) {
    $ch = curl_init($url);
    curl_setopt_array($ch, array(CURLOPT_RETURNTRANSFER=>1,CURLOPT_FOLLOWLOCATION=>1,CURLOPT_TIMEOUT=>60,CURLOPT_SSL_VERIFYPEER=>0,CURLOPT_USERAGENT=>'vbdl'));
    $bin = curl_exec($ch);
    $out[$rel.'_http'] = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
  }
  if (!is_string($bin) || $bin === '') { $bin = @file_get_contents($url); }
  if (!is_string($bin) || $bin === '') { $out[$rel] = 'FAIL fetch'; continue; }
  $dest = $base . $rel;
  if (!is_dir(dirname($dest))) { @mkdir(dirname($dest), 0755, true); }
  $ok = @file_put_contents($dest, $bin);
  $out[$rel] = ($ok !== false)
    ? ('OK '.strlen($bin).' rm='.(strpos($bin,'removeDmUploadWidgets')!==false?'1':'0').' pmchat='.(strpos($bin,'pmchat')!==false?'1':'0'))
    : 'FAIL write';
}
# Patch any leftover cache-bust string in PHP templates under packages
foreach (glob($base.'/core/packages/vbdlportal/*.php') as $p) {
  $c = @file_get_contents($p);
  if (!is_string($c)) continue;
  $n = str_replace(array('post-upload.js?v=20260905','post-upload.css?v=20260905'), array('post-upload.js?v=20260913mc2','post-upload.css?v=20260913mc2'), $c);
  if ($n !== $c) { @file_put_contents($p, $n); $out['patched_'.basename($p)] = 1; }
}
@file_put_contents($base.'/vbdlmanager/_deploy_mc_remove.json', json_encode($out));
